#include <stdio.h>

int main(void) {
    int tag = 0xA7;
    int count = 0;
    int zone = (tag & 0xF0) >> 4;
    // 구역 10은 상차 L과 포장 P, 구역 11은 포장 P만, 그 밖의 구역은 보관 S만 거쳐요.
    switch (zone) {
        case 10:
            printf("L");
            count++;
        case 11:
            printf("P");
            count++;
            break;
        default:
            printf("S");
            count++;
    }
    printf(" %d", count);
    return 0;
}
